"""Editorial annotations for the engineering paper catalog. No experiments were run."""
R = {}
def add(id, short, obj, problem, method, validation, use, borrow, boundary, difficulty, source='', priority='按课题选读'):
    R[id] = dict(short_name=short, engineering_object=obj, research_problem=problem,
        method=method, reported_validation=validation, citation_use=use,
        suggested_experiment=borrow, limitations=boundary, reproduction=difficulty,
        evidence_url=source, priority=priority,
        code_status='本次未确认作者代码', code_url='', code_scope='未核验完整实现',
        data_status='本次未确认可独立下载的完整论文数据', data_url='',
        reading_status='未读', run_status='未运行论文实验')

